import React, { useState } from 'react';
import { 
  Box, 
  Container, 
  Typography, 
  TextField, 
  Button, 
  Card, 
  CardContent, 
  Grid, 
  FormControl, 
  InputLabel, 
  Select, 
  MenuItem, 
  FormControlLabel, 
  Checkbox, 
  Stepper, 
  Step, 
  StepLabel,
  Alert,
  Divider
} from '@mui/material';
import { 
  Business, 
  AccountBalance, 
  AdminPanelSettings,
  ArrowForward,
  ArrowBack
} from '@mui/icons-material';

const RegistrationPage = () => {
  const [activeStep, setActiveStep] = useState(0);
  const [userType, setUserType] = useState('');
  const [registrationStatus, setRegistrationStatus] = useState('pending'); // pending, approved, rejected
  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    organization: '',
    designation: '',
    municipality: '',
    lenderType: '',
    adminRole: '',
    password: '',
    confirmPassword: '',
    termsAccepted: false
  });

  const steps = ['User Type', 'Personal Information', 'Organization Details', 'Account Setup'];

  const userTypes = [
    {
      type: 'municipal',
      title: 'Municipal Commissioner',
      icon: <Business sx={{ fontSize: 40, color: 'primary.main' }} />,
      description: 'Submit projects and manage municipal financing'
    },
    {
      type: 'lender',
      title: 'Lender/Funder',
      icon: <AccountBalance sx={{ fontSize: 40, color: 'success.main' }} />,
      description: 'Fund municipal projects and manage investments'
    },
    {
      type: 'admin',
      title: 'Administrator',
      icon: <AdminPanelSettings sx={{ fontSize: 40, color: 'warning.main' }} />,
      description: 'Platform management and oversight'
    }
  ];

  const handleNext = () => {
    setActiveStep((prevStep) => prevStep + 1);
  };

  const handleBack = () => {
    setActiveStep((prevStep) => prevStep - 1);
  };

  const handleInputChange = (field) => (event) => {
    setFormData({
      ...formData,
      [field]: event.target.value
    });
  };

  const handleUserTypeSelect = (type) => {
    setUserType(type);
    handleNext();
  };

  const handleRegistrationSubmit = () => {
    console.log('Registration submitted:', formData);
    setRegistrationStatus('pending');
    // Here you would typically send the data to your backend
    alert('Registration submitted successfully! Your application is under review. You will receive an email confirmation once approved.');
  };

  const renderUserTypeSelection = () => (
    <Box sx={{ textAlign: 'center' }}>
      <Typography variant="h4" gutterBottom sx={{ mb: 4 }}>
        Choose Your Role
      </Typography>
      <Typography variant="body1" color="text.secondary" sx={{ mb: 6 }}>
        Select the type of account that best describes your role in the municipal financing ecosystem
      </Typography>
      <Grid container spacing={4} justifyContent="center">
        {userTypes.map((userTypeOption) => (
          <Grid item xs={12} sm={6} md={4} key={userTypeOption.type}>
            <Card 
              sx={{ 
                cursor: 'pointer',
                transition: 'all 0.3s ease',
                '&:hover': { 
                  transform: 'translateY(-8px)',
                  boxShadow: 8
                },
                border: userType === userTypeOption.type ? '2px solid' : '2px solid transparent',
                borderColor: 'primary.main'
              }}
              onClick={() => handleUserTypeSelect(userTypeOption.type)}
            >
              <CardContent sx={{ p: 4, textAlign: 'center' }}>
                <Box sx={{ mb: 2 }}>
                  {userTypeOption.icon}
                </Box>
                <Typography variant="h6" gutterBottom sx={{ fontWeight: 'bold' }}>
                  {userTypeOption.title}
                </Typography>
                <Typography variant="body2" color="text.secondary">
                  {userTypeOption.description}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
        ))}
      </Grid>
    </Box>
  );

  const renderPersonalInformation = () => (
    <Box>
      <Typography variant="h5" gutterBottom sx={{ mb: 4 }}>
        Personal Information
      </Typography>
      <Grid container spacing={3}>
        <Grid item xs={12} sm={6}>
          <TextField
            fullWidth
            label="First Name"
            value={formData.firstName}
            onChange={handleInputChange('firstName')}
            required
          />
        </Grid>
        <Grid item xs={12} sm={6}>
          <TextField
            fullWidth
            label="Last Name"
            value={formData.lastName}
            onChange={handleInputChange('lastName')}
            required
          />
        </Grid>
        <Grid item xs={12} sm={6}>
          <TextField
            fullWidth
            label="Email Address"
            type="email"
            value={formData.email}
            onChange={handleInputChange('email')}
            required
          />
        </Grid>
        <Grid item xs={12} sm={6}>
          <TextField
            fullWidth
            label="Phone Number"
            value={formData.phone}
            onChange={handleInputChange('phone')}
            required
          />
        </Grid>
        <Grid item xs={12}>
          <TextField
            fullWidth
            label="Designation"
            value={formData.designation}
            onChange={handleInputChange('designation')}
            required
          />
        </Grid>
      </Grid>
    </Box>
  );

  const renderOrganizationDetails = () => (
    <Box>
      <Typography variant="h5" gutterBottom sx={{ mb: 4 }}>
        Organization Details
      </Typography>
      <Grid container spacing={3}>
        <Grid item xs={12}>
          <TextField
            fullWidth
            label="Organization Name"
            value={formData.organization}
            onChange={handleInputChange('organization')}
            required
          />
        </Grid>
        {userType === 'municipal' && (
          <Grid item xs={12}>
            <TextField
              fullWidth
              label="Municipality"
              value={formData.municipality}
              onChange={handleInputChange('municipality')}
              required
            />
          </Grid>
        )}
        {userType === 'lender' && (
          <Grid item xs={12}>
            <FormControl fullWidth>
              <InputLabel>Lender Type</InputLabel>
              <Select
                value={formData.lenderType}
                label="Lender Type"
                onChange={handleInputChange('lenderType')}
              >
                <MenuItem value="bank">Bank</MenuItem>
                <MenuItem value="nbfc">NBFC</MenuItem>
                <MenuItem value="fund">Investment Fund</MenuItem>
                <MenuItem value="government">Government Agency</MenuItem>
                <MenuItem value="multilateral">Multilateral Agency</MenuItem>
                <MenuItem value="other">Other</MenuItem>
              </Select>
            </FormControl>
          </Grid>
        )}
        {userType === 'admin' && (
          <Grid item xs={12}>
            <FormControl fullWidth>
              <InputLabel>Admin Role</InputLabel>
              <Select
                value={formData.adminRole}
                label="Admin Role"
                onChange={handleInputChange('adminRole')}
              >
                <MenuItem value="super">Super Admin</MenuItem>
                <MenuItem value="moderator">Moderator</MenuItem>
                <MenuItem value="analyst">Analyst</MenuItem>
              </Select>
            </FormControl>
          </Grid>
        )}
      </Grid>
    </Box>
  );

  const renderAccountSetup = () => (
    <Box>
      <Typography variant="h5" gutterBottom sx={{ mb: 4 }}>
        Account Setup
      </Typography>
      <Grid container spacing={3}>
        <Grid item xs={12} sm={6}>
          <TextField
            fullWidth
            label="Password"
            type="password"
            value={formData.password}
            onChange={handleInputChange('password')}
            required
          />
        </Grid>
        <Grid item xs={12} sm={6}>
          <TextField
            fullWidth
            label="Confirm Password"
            type="password"
            value={formData.confirmPassword}
            onChange={handleInputChange('confirmPassword')}
            required
          />
        </Grid>
        <Grid item xs={12}>
          <FormControlLabel
            control={
              <Checkbox
                checked={formData.termsAccepted}
                onChange={(e) => setFormData({...formData, termsAccepted: e.target.checked})}
                required
              />
            }
            label="I agree to the Terms and Conditions and Privacy Policy"
          />
        </Grid>
        <Grid item xs={12}>
          <Alert severity="info">
            <Typography variant="body2">
              <strong>Platform Access Fee:</strong> ₹50,000 per year for full platform access. 
              This includes project submission, funding commitments, and advanced analytics.
            </Typography>
          </Alert>
        </Grid>
      </Grid>
    </Box>
  );

  const getStepContent = (step) => {
    switch (step) {
      case 0:
        return renderUserTypeSelection();
      case 1:
        return renderPersonalInformation();
      case 2:
        return renderOrganizationDetails();
      case 3:
        return renderAccountSetup();
      default:
        return 'Unknown step';
    }
  };

  return (
    <Container maxWidth="md" sx={{ py: 4 }}>
      <Card sx={{ p: 4 }}>
        {/* Header */}
        <Box sx={{ textAlign: 'center', mb: 4 }}>
          <Typography variant="h3" component="h1" gutterBottom sx={{ fontWeight: 'bold', color: 'primary.main' }}>
            Munify Registration
          </Typography>
          <Typography variant="body1" color="text.secondary">
            Join India's premier municipal funding platform
          </Typography>
        </Box>

        {/* Stepper */}
        <Stepper activeStep={activeStep} sx={{ mb: 4 }}>
          {steps.map((label) => (
            <Step key={label}>
              <StepLabel>{label}</StepLabel>
            </Step>
          ))}
        </Stepper>

        {/* Step Content */}
        <Box sx={{ mb: 4 }}>
          {getStepContent(activeStep)}
        </Box>

        {/* Navigation Buttons */}
        {activeStep > 0 && (
          <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
            <Button
              onClick={handleBack}
              startIcon={<ArrowBack />}
              disabled={activeStep === 0}
            >
              Back
            </Button>
            {activeStep === steps.length - 1 ? (
              <Button
                variant="contained"
                onClick={handleRegistrationSubmit}
                endIcon={<ArrowForward />}
                disabled={!formData.termsAccepted}
              >
                Complete Registration
              </Button>
            ) : (
              <Button
                variant="contained"
                onClick={handleNext}
                endIcon={<ArrowForward />}
                disabled={activeStep === 0}
              >
                Next
              </Button>
            )}
          </Box>
        )}

        {/* Registration Status Display */}
        {registrationStatus === 'pending' && (
          <Box sx={{ mb: 4 }}>
            <Alert severity="info" sx={{ textAlign: 'center' }}>
              <Typography variant="h6" gutterBottom>
                🕐 Registration Under Review
              </Typography>
              <Typography variant="body2">
                Your registration has been submitted successfully and is currently under administrative review. 
                You will receive an email notification once your account is approved.
              </Typography>
              <Typography variant="body2" sx={{ mt: 1, fontWeight: 'bold' }}>
                Expected review time: 24-48 hours
              </Typography>
            </Alert>
          </Box>
        )}

        {/* Login Link */}
        <Divider sx={{ my: 4 }} />
        <Box sx={{ textAlign: 'center' }}>
          <Typography variant="body2" color="text.secondary">
            Already have an account?{' '}
            <Button color="primary" variant="text">
              Sign In
            </Button>
          </Typography>
        </Box>
      </Card>
    </Container>
  );
};

export default RegistrationPage;
